window.LION_KB={"meta": {"name": "Lions Guide (unofficial)", "built": "2026-11-18", "note": "Curated seed knowledge base. Paraphrased from lionsclubs.org pages and Lions-affiliated sites; each entry links to its source. Run the crawler to add the full resource center.", "version": "0.7.1", "checked": "2026-11-18", "build": "2026-11-18 16:21 UTC", "logo": "logo.png"}, "sources": {"mission-history": {"url": "https://lionsclubs.org/en/discover-our-clubs/mission-and-history", "label": "Lions Clubs International: Our History", "tier": "official"}, "about-node": {"url": "https://lionsclubs.org/node/14981", "label": "Lions Clubs International: About", "tier": "official"}, "new-members": {"url": "https://www.lionsclubs.org/en/resources-for-members/new-members", "label": "New Member Welcome", "tier": "official"}, "mrc": {"url": "https://lionsclubs.org/en/member-resource-center", "label": "Member Resource Center", "tier": "official"}, "service-programs": {"url": "https://lionsclubs.org/en/service-programs", "label": "Service Programs", "tier": "official"}, "club-types": {"url": "https://lionsclubs.org/node/14991", "label": "Club and membership types", "tier": "official"}, "join": {"url": "https://lionsclubs.org/join", "label": "Join Lions", "tier": "official"}, "ethics": {"url": "https://www.lionsclubs.org/sites/default/files/Board-Policy-Manual/Chapter_6_en.pdf", "label": "Board Policy Manual, Chapter VI: Code of Ethics", "tier": "official"}, "gst": {"url": "https://lions100.lionsclubs.org/en/resources-for-members/resource-center/gst-toolbox", "label": "Global Service Team Toolbox", "tier": "official"}, "campus": {"url": "https://lions100.lionsclubs.org/en/resources-for-members/resource-center/campus-lions-club", "label": "Campus Lions Club", "tier": "official"}, "leo-faqs": {"url": "https://lionsclubs.org/en/resources-for-members/resource-center/leo-faqs", "label": "Leo Club FAQs", "tier": "official"}, "leo-lion": {"url": "https://lionsclubs.org/en/resources-for-members/resource-center/leo-lion-program", "label": "Leo-Lion Program", "tier": "official"}, "lcif-blog": {"url": "https://lionsclubs.org/en/blog/A-World-in-Need,-a-Foundation-of-Support", "label": "A World in Need, a Foundation of Support (LCIF)", "tier": "official"}, "gma": {"url": "https://lionsclubs.org/en/global", "label": "Global Membership Approach", "tier": "official"}, "young-lions": {"url": "https://lionsclubs.org/hi/node/16981", "label": "Young Lions hub", "tier": "official"}, "options": {"url": "https://lions100.lionsclubs.org/node/18641", "label": "Membership options", "tier": "official"}, "texas-history": {"url": "https://texaslions.org/?p=877", "label": "Texas Lions: Our Mission As Lions (history timeline)", "tier": "affiliate"}, "e-clubhouse-history": {"url": "https://e-clubhouse.org/sites/greater_orange_county/page-7.php", "label": "Lions club site: Mission, vision and history", "tier": "affiliate"}, "nz-fact": {"url": "https://lionsclubs.org.nz/download_file/force/323/266", "label": "Lions Clubs International publication ME33 (via Lions NZ)", "tier": "affiliate"}, "purposes": {"url": "https://lionsclubs.org.nz/download_file/force/2602/266", "label": "Constitution and By-Laws text (via Lions NZ)", "tier": "affiliate"}, "au-ethics": {"url": "https://lionsclubs.org.au/our-ethics-purpose", "label": "Lions Australia: Ethics and Purpose", "tier": "affiliate"}, "idaho-story": {"url": "https://sites.google.com/view/idahospringslions/about-lions/our-story", "label": "Lions club site: Our Story", "tier": "affiliate"}, "wotton": {"url": "https://www.wottonlions.org/international/", "label": "Lions club site: Lions International", "tier": "affiliate"}, "club-const": {"url": "https://lionsdistrict306c2.org/assets/uploads/downloads/Club_Constitution_By_Laws.pdf", "label": "Standard Club Constitution and By-Laws (FY 2023-24 template, Lions-affiliated copy)", "tier": "affiliate"}, "intl-const": {"url": "https://lionsdistrict306c2.org/assets/uploads/downloads/International_Constitution.pdf", "label": "International Constitution and By-Laws (revised July 2023, Lions-affiliated copy)", "tier": "affiliate"}, "zone-ebook": {"url": "https://a15lions.org/pages/uploads/Directory/5_ZC-RC_e-Book.pdf", "label": "Zone and Region Chairperson e-Book (Lions Clubs International, district-hosted)", "tier": "affiliate"}, "club-guide-2025": {"url": "https://lions.hr/sites/default/files/za_rukovodstvo_klubova_vodic_2025.pdf", "label": "Lions club leader guide 2025 (district-hosted)", "tier": "affiliate"}, "presidents-deck": {"url": "https://www.slideshare.net/DistrictGovernor/121clubpresidentpptpptx", "label": "Lions Club President course slides (Lions University 121)", "tier": "affiliate"}, "order-business": {"url": "https://www.buildersclub.org/wp-content/uploads/sites/7/2020/12/Parliamentary-Procedure-.pdf", "label": "How to conduct a meeting using parliamentary procedure (general guide)", "tier": "general"}, "order-business2": {"url": "https://www.extension.purdue.edu/county/vanderburgh/_docs/1-presidents-guide.pdf", "label": "Club president's guide, Purdue Extension (general guide)", "tier": "general"}, "zone-resources": {"url": "https://lionsclubs.org/en/resources-for-members/resource-center/zone-region-chairpersons", "label": "Managing your Zone and Region (Member Resource Center)", "tier": "official"}, "leaders-page": {"url": "https://lionsclubs.org/en/discover-our-clubs/our-leaders", "label": "Lions Clubs International: Our Leaders", "tier": "official"}, "lyon-release": {"url": "https://www.newsfilecorp.com/release/304051/Lions-Clubs-International-Announces-Mark-S.-Lyon-as-20262027-International-President", "label": "Lions International news release: Mark S. Lyon, 2026-2027 International President", "tier": "official"}, "lcif-toolkit": {"url": "https://www.lionsclubs.org/en/member-resource-center/leaders/resources/lcif-leadership-toolkit", "label": "LCIF Leadership Toolkit", "tier": "official"}, "club-officer-nz": {"url": "https://lionsclubs.org.nz/download_file/view/208/296", "label": "Lions guide for new club officers (New Zealand, based on the International guide)", "tier": "affiliate"}, "brand-page": {"url": "https://www.lionsclubs.org/en/resources-for-members/brand-guidelines", "label": "Brand Guidelines, Logos and Brand", "tier": "official"}, "lions-name": {"url": "https://www.e-clubhouse.org/sites/potomacvalleymd/page-9.php", "label": "Lions club guide: About Lions (motto, slogan and history)", "tier": "general"}}, "tour": ["what-is-lions", "mission-vision", "history", "global-causes", "lcif", "club-types", "how-to-join", "new-member-first-steps"], "entries": [{"id": "what-is-lions", "cat": "Basics", "level": "new", "title": "What is Lions Clubs International?", "questions": ["what is lions club", "what is lionism", "who are the lions", "tell me about lions clubs international", "what do lions do", "is lions a service club", "how many members does lions have", "how many clubs are there", "how many countries are lions in", "how big is lions clubs international", "are lions a religious group"], "answer": "Lions Clubs International is the world's largest service club organisation. Ordinary people join local clubs, called Lions clubs, and volunteer their time and money to help their communities and people in need. A member is called a Lion. The motto is \"We Serve\".", "facts": ["About 1.4 million members in roughly 49,000 to 50,000 clubs", "Active in over 200 countries and geographic areas", "Over 100 years of service, founded 1917", "Lions serve hundreds of millions of people every year", "Lions and Leos serve through five global causes and other local projects"], "tags": ["lions", "lionism", "overview", "service club", "volunteer", "organization", "organisation", "about"], "related": ["mission-vision", "history", "global-causes", "how-to-join"], "src": ["new-members", "mission-history"]}, {"id": "mission-vision", "cat": "Basics", "level": "new", "title": "Mission and vision", "questions": ["what is the mission of lions", "lions vision statement", "why do lions exist", "what is lions mission statement"], "answer": "The mission is to empower Lions clubs, volunteers and partners to improve health and well-being, strengthen communities and support those in need. They do this through humanitarian service and grants, and they also encourage peace and international understanding. The vision is to be the global leader in community and humanitarian service.", "facts": ["Mission wording is from Lions Clubs International's own About page", "Vision wording is as printed in Lions club constitutions"], "tags": ["mission", "vision", "purpose", "goal", "why"], "related": ["motto", "core-values", "purposes"], "src": ["about-node", "au-ethics"]}, {"id": "motto", "cat": "Basics", "level": "new", "title": "The Lions motto: We Serve", "questions": ["what is the lions motto", "we serve meaning", "who chose the motto", "lions slogan", "what does lions stand for acronym"], "answer": "The motto is \"We Serve\". It was chosen in 1954 after a contest among Lions, and the winning suggestion came from a Lion in Ontario, Canada. The word LIONS is also used as an acronym: Liberty, Intelligence, Our Nation's Safety.", "facts": ["Motto adopted 1954", "Acronym LIONS: Liberty, Intelligence, Our Nation's Safety"], "tags": ["motto", "we serve", "slogan", "acronym", "liberty intelligence", "stand for", "stands for", "lions stand for", "name meaning"], "related": ["what-is-lions", "emblem-colors"], "src": ["texas-history", "nz-fact"]}, {"id": "history", "cat": "Basics", "level": "new", "title": "A short history of Lions", "questions": ["history of lions club", "when was lions club founded", "who founded lions", "how did lions start", "lions club timeline", "when did lions become international", "who started the lions club", "who started lions", "when did lions begin", "where did lions club start", "how old is lions club", "how long has lions existed", "how old is the organization"], "answer": "Lions began in 1917, when Chicago business leader Melvin Jones asked his business club to look beyond business and work for the betterment of their communities and the world. Within three years the association was international, and it has grown into the largest service club organisation in the world.", "facts": ["1917: Melvin Jones, a 38-year-old Chicago businessman, calls on his club to serve communities", "1920: first club outside the US, in Canada. Mexico followed in 1927", "1925: Helen Keller challenges Lions to become \"knights of the blind\"", "1954: \"We Serve\" chosen as the official motto", "1957: Lions launch youth programs, including Leo clubs", "1968: Lions Clubs International Foundation (LCIF) established", "2018: diabetes added as a global focus"], "tags": ["history", "founded", "1917", "melvin jones", "timeline", "origin", "begin", "start", "founder", "chicago"], "related": ["helen-keller", "lcif", "global-causes"], "src": ["texas-history", "e-clubhouse-history", "idaho-story"]}, {"id": "helen-keller", "cat": "Basics", "level": "new", "title": "Helen Keller and Lions", "questions": ["helen keller lions", "why do lions work on vision", "why is vision important to lions", "knights of the blind", "why do lions care about eyesight", "why are lions focused on eyesight"], "answer": "In 1925, at the Lions international convention in Cedar Point, Ohio, Helen Keller challenged Lions to become \"knights of the blind in the crusade against darkness\". That challenge is why sight and preventing blindness have been at the heart of Lions service ever since.", "facts": ["Convention: Cedar Point, Ohio, USA, 1925", "Lions' sight work later grew into the international SightFirst program"], "tags": ["helen keller", "blind", "sight", "vision", "history"], "related": ["cause-vision", "history"], "src": ["texas-history", "wotton"]}, {"id": "emblem-colors", "cat": "Basics", "level": "new", "title": "Lions colours and emblem", "questions": ["lions club colors", "purple and gold meaning", "lions emblem", "lions logo meaning", "lions flag"], "answer": "Lions colours are purple and gold. The Lions emblem has the word \"Lions\" at the top and \"International\" at the bottom, with two lions facing both past and future. The official Lions International flag has a white background with a gold fringe for indoor use or a gold border for outdoor use.", "facts": ["Purple and gold were approved at the early conventions", "Flag rules are in the Board Policy Manual, Chapter VI"], "tags": ["colors", "colours", "purple", "gold", "emblem", "logo", "flag"], "related": ["motto", "code-of-ethics"], "src": ["ethics", "e-clubhouse-history"]}, {"id": "code-of-ethics", "cat": "Values", "level": "new", "title": "The Lions Code of Ethics", "questions": ["lions code of ethics", "what are the ethics of lions", "lion rules of conduct", "lions values for members", "how should a lion behave"], "answer": "The Code of Ethics is a personal guide for how each Lion should act. In plain words: work with quality and industry, seek success but never at the cost of self-respect, do not build yourself up by tearing others down, settle doubts about right and wrong against yourself, treat friendship as an end and not a means, be a good citizen, help those in distress, and be careful with criticism and generous with praise.", "facts": ["The Code has eight statements, each starting with TO, WHENEVER or ALWAYS", "The Purposes describe what the organisation aims to do; the Code describes how members personally behave"], "tags": ["ethics", "code", "conduct", "behaviour", "behavior", "integrity", "rules"], "related": ["core-values", "purposes"], "src": ["ethics", "nz-fact"]}, {"id": "core-values", "cat": "Values", "level": "new", "title": "Lions core values", "questions": ["lions core values", "what values do lions have", "lions ethical standards", "integrity accountability lions"], "answer": "Lions' ethical standards rest on core values: commitment to service, dedication to excellence, appreciation for diversity, dynamic collaboration, personal and professional integrity, and a spirit of innovation. The association says it has no tolerance for ethical violations.", "facts": ["Also stressed: safeguarding association assets, honouring commitments, and teamwork", "Source is the Board Policy Manual, Chapter VI"], "tags": ["values", "service", "excellence", "diversity", "integrity", "innovation", "accountability", "teamwork"], "related": ["code-of-ethics", "mission-vision"], "src": ["ethics"]}, {"id": "purposes", "cat": "Values", "level": "member", "title": "The Purposes of Lions Clubs International", "questions": ["lions purposes", "objects of lions", "what are the purposes of lions clubs international"], "answer": "The International Constitution lists eight Purposes, including organising and supervising Lions clubs, fostering international understanding, promoting good government and citizenship, caring for community welfare, uniting clubs in friendship, providing an open forum without partisan politics or sectarian religion, and encouraging service without personal financial reward.", "facts": ["Ask 'the eight purposes' for the full list"], "tags": ["purposes", "objects"], "related": ["intl-purposes", "code-of-ethics", "mission-vision", "club-constitution"], "src": ["purposes", "au-ethics"]}, {"id": "global-causes", "cat": "Service", "level": "new", "title": "Global causes: what Lions work on", "questions": ["what are the global causes", "what causes do lions support", "areas of service lions", "how many global causes", "five global causes", "eight global causes"], "answer": "Lions focus their worldwide service on five global causes: diabetes, vision, hunger, the environment and childhood cancer. On top of these, Lions Clubs International Foundation also funds disaster relief, youth programs and wider humanitarian work, which is why the Join page speaks of eight causes.", "facts": ["Five global causes: Diabetes, Vision, Hunger, Environment, Childhood Cancer", "Other service areas: Youth, Disaster Relief, Humanitarian Efforts", "Each cause has beginner, intermediate and advanced project ideas for clubs", "Clubs can also serve local needs outside these causes"], "tags": ["causes", "global causes", "service", "projects", "focus areas", "what lions do"], "related": ["cause-diabetes", "cause-vision", "cause-hunger", "cause-environment", "cause-childhood-cancer", "disaster-relief"], "src": ["service-programs", "join", "lcif-blog"]}, {"id": "cause-diabetes", "cat": "Service", "level": "new", "title": "Diabetes", "questions": ["lions diabetes", "diabetes screening lions", "diabetes camps", "strides for diabetes", "what do lions do about diabetes", "diabetes support group"], "answer": "Lions work to reduce how common diabetes is and to improve life for people living with it. Clubs run Type 2 diabetes screening events, \"Strides\" walks and runs that raise awareness, diabetes camps for young people, and peer support groups.", "facts": ["Type 2 Diabetes Screening: clubs use step-by-step guides", "Strides for Diabetes Awareness: any physical activity, such as a run or dance event", "Diabetes Camps: help young people build diabetes management skills", "Diabetes Support Groups: peer groups sponsored by a club or district", "Diabetes became a global focus in 2018"], "tags": ["diabetes", "sugar", "screening", "camp", "health", "strides"], "related": ["global-causes", "lcif"], "src": ["service-programs", "idaho-story"]}, {"id": "cause-vision", "cat": "Service", "level": "new", "title": "Vision and eye care", "questions": ["lions vision", "eye care lions", "vision screening", "eye bank", "lions kidsight", "recycle eyeglasses", "donate glasses", "sightfirst", "blindness prevention"], "answer": "Vision is Lions' oldest cause. Clubs screen children and adults for vision problems, run the KidSight program for children from 6 months old, sponsor eye banks that supply eye tissue for sight restoration, and collect used eyeglasses for people who cannot afford them.", "facts": ["Vision Screening: with medical professionals and community leaders", "Lions KidSight: screening and referral from age 6 months", "Lions Eye Banks: recover, test, store and distribute eye tissue", "Eyeglass Recycling: used glasses go to the Lions Recycle For Sight program", "LCIF figures from Campaign 100 material: 9.1 million cataract surgeries performed, and nearly 75% of vision impairment is preventable or curable"], "tags": ["vision", "eye", "eyes", "sight", "blind", "blindness", "glasses", "eyeglasses", "cataract", "screening", "kidsight", "eye bank"], "related": ["helen-keller", "global-causes", "lcif"], "src": ["service-programs", "lcif-blog", "wotton"]}, {"id": "cause-hunger", "cat": "Service", "level": "new", "title": "Hunger", "questions": ["lions hunger", "food bank lions", "what do lions do about hunger", "lions food security", "feed the hungry"], "answer": "Through the hunger cause, Lions work to make sure everyone in a community has access to nutritious food. Clubs support food banks and food distribution, and LCIF grants can fund food bank and distribution infrastructure, transport, and commercial refrigeration and freezers.", "facts": ["Goal: improve food security and access to nutritious food", "Grants can pay for food bank equipment and transport"], "tags": ["hunger", "food", "nutrition", "food bank", "malnutrition"], "related": ["global-causes", "lcif-grants"], "src": ["join", "lcif-blog"]}, {"id": "cause-environment", "cat": "Service", "level": "new", "title": "Environment", "questions": ["lions environment", "lions clean water", "environment projects", "tree planting lions", "lions sanitation"], "answer": "The environment cause is about protecting and restoring the natural world to improve people's wellbeing. LCIF funding in this area has paid for water tanks, wells and pumps, water purification for schools and clinics, and toilets and sanitation where none exist.", "facts": ["Goal: sustainably protect and restore the environment", "LCIF Campaign 100 material noted that at least 1.8 billion people use drinking water contaminated by faecal matter"], "tags": ["environment", "water", "sanitation", "green", "climate", "trees", "clean"], "related": ["global-causes", "lcif-grants"], "src": ["join", "lcif-blog"]}, {"id": "cause-childhood-cancer", "cat": "Service", "level": "new", "title": "Childhood cancer", "questions": ["lions childhood cancer", "children with cancer", "what do lions do for kids with cancer", "pediatric oncology"], "answer": "Lions support children and families affected by childhood cancer. Funding has gone to pediatric oncology services in developing countries, medical and lab equipment, vehicles for patient travel, and family lodging and camp facilities. Lions also work with the partner Global HOPE to improve standards of care.", "facts": ["A Childhood Cancer Grant program exists, with its own criteria and application form", "Campaign 100 material: a child is diagnosed about every two minutes; survival is around 80% in high-income countries but may be only 10 to 20% in low- and middle-income countries"], "tags": ["childhood cancer", "cancer", "children", "kids", "hospital", "oncology", "family"], "related": ["global-causes", "lcif-grants"], "src": ["join", "lcif-blog"]}, {"id": "disaster-relief", "cat": "Service", "level": "new", "title": "Disaster relief", "questions": ["lions disaster relief", "flood relief", "earthquake help lions", "disaster relief fund", "emergency grants"], "answer": "Lions respond when disasters hit, providing immediate needs like food, water, clothing and medical supplies, and later helping rebuild homes and facilities. People can donate to the Disaster Relief Fund, which is reserved only for disaster relief.", "facts": ["LCIF has invested about US$130 million in disaster-related grants since 1970 (Campaign 100 material)", "Donations to LCIF go to either the Empowering Service Fund or the Disaster Relief Fund"], "tags": ["disaster", "relief", "flood", "earthquake", "emergency", "hurricane", "fund"], "related": ["lcif", "lcif-grants"], "src": ["lcif-blog", "mrc"]}, {"id": "youth", "cat": "Service", "level": "new", "title": "Youth programs", "questions": ["lions youth programs", "lions for kids", "peace poster contest", "youth camps and exchange", "lions quest", "how do lions help young people"], "answer": "Lions run several programs for young people: Leo clubs for ages 12 to 30, the Youth Camps and Exchange program that promotes understanding and peace, the annual Peace Poster and Peace Essay contests, and Lions Quest, a school-based program for young people.", "facts": ["Youth Camps and Exchange excludes tourism, academic study and employment", "Lions Quest has reached 17+ million students in over 100 countries (Campaign 100 material)", "Peace Poster and Essay entries move from club to district to multiple district, then to Lions headquarters"], "tags": ["youth", "kids", "children", "students", "peace poster", "essay", "camp", "exchange", "lions quest", "school"], "related": ["leo-clubs", "young-lions"], "src": ["service-programs", "lcif-blog", "mrc"]}, {"id": "service-programs", "cat": "Service", "level": "member", "title": "Service programs clubs can run", "questions": ["lions service programs", "service project ideas", "what projects can my club do", "project planners", "lions programs list"], "answer": "Lions International offers ready-made service programs so clubs do not start from scratch: Type 2 Diabetes Screening, Strides for Diabetes Awareness, Diabetes Camps and Support Groups, Vision Screening, Lions KidSight, Lions Eye Banks, Eyeglass Recycling, and Youth Camps and Exchange. Downloadable Service Project Planners and beginner-to-advanced ideas exist for each cause.", "facts": ["Projects are grouped by global cause", "The Global Service Team site gathers the planners, ideas and grants"], "tags": ["programs", "projects", "planner", "ideas", "club projects"], "related": ["gst", "global-causes"], "src": ["service-programs", "gst"]}, {"id": "lcif", "cat": "Foundation", "level": "new", "title": "LCIF: the Lions foundation", "questions": ["what is lcif", "lions clubs international foundation", "what is the lions foundation", "lcif history", "who funds lcif", "how is lcif funded"], "answer": "LCIF, the Lions Clubs International Foundation, is the charitable arm of Lions. Founded in 1968, it gives grants that power Lions' service, and has awarded over US$1.3 billion so far. Its work centres on three goals: health and well-being, stronger communities, and support for people in need.", "facts": ["Founded 1968", "Funded by Lions, corporate, government and foundation partners, and other supporters", "Grants support Lions' local and global projects", "Donations on lionsclubs.org support LCIF"], "tags": ["lcif", "foundation", "grants", "charity", "donate", "funding"], "related": ["lcif-grants", "disaster-relief", "global-causes"], "src": ["new-members", "lcif-blog"]}, {"id": "lcif-grants", "cat": "Foundation", "level": "member", "title": "What LCIF grants and donations pay for", "questions": ["how do i get an lcif grant", "what do lcif grants fund", "where does my donation go", "lions grants", "campaign 100", "how to donate to lions"], "answer": "LCIF grants have paid for expanded eye care, education programs, disaster recovery, diabetes screening and camps, pediatric cancer equipment and family lodging, food bank infrastructure, and clean water and sanitation. Donations go to one of two funds: the Empowering Service Fund for all causes, or the Disaster Relief Fund for disasters only.", "facts": ["Campaign 100 was LCIF's centennial fundraising campaign", "Each grant type has its own criteria and application form; check the Member Resource Center for the current ones"], "tags": ["grants", "donate", "donation", "campaign 100", "funding", "empowering service fund"], "related": ["lcif", "disaster-relief"], "src": ["lcif-blog", "gst"]}, {"id": "how-to-join", "cat": "Joining", "level": "new", "title": "How to join Lions", "questions": ["how do i join lions", "how to become a lion", "join lions club", "how can i become a member", "find a lions club near me", "club locator", "can i join", "is there a lions club in my city", "is there a lions club in my town", "is there a club near me"], "answer": "Use the Find a Club tool on the Lions website to see clubs near you, then contact one and attend a meeting or a service project. If no club suits you, you can also start a new one. There are different club types, such as traditional, specialty, campus and Leo clubs, so you can pick what fits your life.", "facts": ["Find a club: lionsclubs.org/en/join", "Membership questions: membership@lionsclubs.org", "Membership types include regular, family, student and Leo"], "tags": ["join", "become", "membership", "member", "find a club", "locator", "near me", "sign up", "apply"], "related": ["club-types", "membership-types", "new-member-first-steps"], "src": ["join", "options", "club-types"]}, {"id": "club-types", "cat": "Joining", "level": "new", "title": "Types of Lions clubs", "questions": ["types of lions clubs", "what kinds of clubs are there", "traditional club", "specialty club", "virtual club", "which club should i join", "club options", "can i attend meetings online", "what is the difference between traditional and specialty clubs", "clubs that meet by video call", "can lions meet on zoom"], "answer": "Most Lions clubs are traditional clubs that meet locally. Other options: specialty clubs, where members share an interest such as a hobby, culture or profession; virtual clubs that meet online or by phone; campus clubs for students; and Leo clubs for young people.", "facts": ["Traditional: service-minded people who meet locally and regularly", "Specialty: shared interest plus commitment to service", "Virtual: some or all meetings held remotely; good for busy or spread-out members", "Campus: students build leadership skills and serve together", "Leo: ages 12 to 30"], "tags": ["club types", "traditional", "specialty", "virtual", "campus", "leo", "options", "online"], "related": ["campus-club", "leo-clubs", "club-branch", "membership-types"], "src": ["club-types", "options"]}, {"id": "membership-types", "cat": "Joining", "level": "new", "title": "Membership types and discounts", "questions": ["membership types", "family membership", "student membership", "lions dues discount", "how much does lions cost", "can my family join together", "what is the fee"], "answer": "Four main kinds of membership: regular, family, student, and Leo. Family membership is for relatives in the same household and has a reduced dues rate. Student membership is for students from the legal age of majority up to under 30 and gives a discount on international dues. Leo members, aged 12 to 30, pay no membership fee. Local club dues vary and are set by each club.", "facts": ["Children cannot be members but can take part in the Cub program", "Leo-Lion members get a 50% discount on international dues", "The pages I collected do not list the actual dues amounts"], "tags": ["membership", "dues", "fees", "cost", "family", "student", "discount", "price", "how much"], "related": ["leo-lion", "campus-club", "how-to-join"], "src": ["club-types", "leo-lion", "campus"]}, {"id": "campus-club", "cat": "Joining", "level": "new", "title": "Campus Lions clubs", "questions": ["campus lions club", "lions club for students", "how to start a campus lions club", "student member program", "charter members for campus club"], "answer": "A Campus Lions club is open to any student, living on or off campus, full-time or part-time. To charter one you need at least 20 charter members, of whom at least five are students. The usual route is to get approved as a registered student club with your school's student activities office.", "facts": ["Benefits: service hours, resume-building training, networking, and Student Member Program discounts", "If the school does not approve, you can charter an independent Campus Lions club, but may lose the school's name, campus venues and funding", "Student Member Program covers students from legal age of majority to under 30"], "tags": ["campus", "student", "college", "university", "charter", "school"], "related": ["club-branch", "young-lions", "leo-lion"], "src": ["campus", "young-lions"]}, {"id": "club-branch", "cat": "Joining", "level": "member", "title": "Club branches", "questions": ["what is a club branch", "start a lions group with five people", "small lions group", "club branch requirements"], "answer": "A club branch is a small group that can meet and serve on its own while getting support from a parent Lions club. It needs only five members, so it suits people who want to form a group but do not have the 20 charter members a full club needs. Alumni of a Campus Lions club can also use a branch to stay connected.", "facts": ["Minimum members: five", "A full new Lions club needs 20 charter members"], "tags": ["club branch", "branch", "five members", "small group", "charter"], "related": ["campus-club", "club-types", "club-branch-rules"], "src": ["campus"]}, {"id": "leo-clubs", "cat": "Youth", "level": "new", "title": "Leo clubs", "questions": ["what are leo clubs", "leo club age", "alpha leo omega leo", "how to start a leo club", "leo club fees", "leo club advisor", "sponsor a leo club", "how old do you have to be to join a leo club", "what is the age limit for leo", "what age can kids join leos", "programme for teenagers", "my teenager wants to volunteer"], "answer": "Leo clubs are youth programs sponsored by Lions clubs for people aged 12 to 30. Alpha Leo clubs are for ages 12 to 18, and Omega Leo clubs are for ages 18 to 30. A sponsoring Lions club names an advisor, ideally someone who enjoys working with young people.", "facts": ["One-time organisation fee: US$100 (certificate, officer kit, sponsor kit, lapel pins)", "Annual levy: US$100 per Leo club, billed to the sponsoring Lions club each July and waived in the year the club is certified", "To charter: organise the club and elect officers, then the sponsoring Lions club president submits the Leo Club Organization Report (Leo-51)", "Certification may take 4 to 6 weeks", "Two or more Lions clubs can jointly sponsor one Leo club"], "tags": ["leo", "leos", "alpha", "omega", "youth", "teen", "advisor", "sponsor", "levy", "leo-51"], "related": ["leo-lion", "youth", "club-types"], "src": ["leo-faqs", "club-types"]}, {"id": "leo-lion", "cat": "Youth", "level": "new", "title": "Leo-Lion program (Leos becoming Lions)", "questions": ["leo to lion", "leo lion program", "what happens when a leo ages out", "leo lion benefits", "leo-lion membership"], "answer": "The Leo-Lion program helps Leos move up into Lions. Current or former Leos who served at least a year and a day, from the legal age of majority through age 35, can join as Leo-Lions. They get a 50% discount on international dues, a waived entrance or charter fee, credit for their Leo years, and access to special scholarships and online learning.", "facts": ["Leo records are automatically closed on June 30 of the Lion year if the Leo has reached the maximum age", "Short-term dual Leo and Lion membership is allowed", "Leo-Lions can serve in any club type, and as liaisons to boards and councils"], "tags": ["leo lion", "leo-lion", "transition", "age out", "graduate", "young lions"], "related": ["leo-clubs", "young-lions", "membership-types"], "src": ["leo-lion"]}, {"id": "young-lions", "cat": "Youth", "level": "new", "title": "Young Lions", "questions": ["young lions", "lions for young adults", "under 30 lions", "young professionals lions", "student member"], "answer": "Young Lions are members aged roughly 40 or younger. If you are 30 or under and in school, the Student Member Program gives discounted dues and extra fee waivers. Campus clubs, specialty clubs, club branches and the Leo-Lion program are all aimed at helping younger people serve in a way that suits them.", "facts": ["Questions: membership@lionsclubs.org", "Young Lions have their own hub on the Lions website"], "tags": ["young lions", "young adults", "youth", "students", "under 30", "under 40"], "related": ["campus-club", "leo-lion", "club-types"], "src": ["young-lions", "gma"]}, {"id": "new-member-first-steps", "cat": "Joining", "level": "new", "title": "Your first steps as a new Lion", "questions": ["new member orientation", "i just joined lions what now", "first steps for new lion", "what should a new lion do first", "how do i begin as a new member"], "answer": "Start by going to your club meetings and joining its service projects. Register on the Lion Portal, complete the New Member Orientation course, and explore the Member Resource Center, which holds Lions news, resources and tools. Following Lions on social media is also encouraged.", "facts": ["Lion Portal: where members register and manage their Lions account", "Lions Learning Center: online courses, including New Member Orientation", "Member Resource Center: news, resources and information"], "tags": ["new member", "orientation", "getting started", "first steps", "lion portal", "learning center", "welcome", "onboarding"], "related": ["glossary-lion-portal", "how-to-join", "gst"], "src": ["new-members", "mrc"]}, {"id": "gst", "cat": "For members", "level": "member", "title": "Global Service Team (GST) toolbox", "questions": ["what is the global service team", "gst toolbox", "service reporting", "kindness matters award", "service journey learn discover act celebrate", "how do clubs report service"], "answer": "The Global Service Team helps clubs find resources and best practices to make their projects better. The toolbox covers service programs and planners, advocacy, service reporting, service awards and LCIF grants. Its service journey has four phases: Learn, Discover, Act and Celebrate.", "facts": ["Kindness Matters Service Award: clubs are nominated at club level; a few each year are recognised for outstanding projects in a global cause", "Lions-Elevance Health Volunteer Days: clubs in specified US cities can apply for grants up to US$2,500 each spring", "Related toolboxes: Global Action Team, Global Leadership Team, Global Membership Team"], "tags": ["gst", "global service team", "toolbox", "reporting", "awards", "kindness matters", "service journey", "advocacy"], "related": ["service-programs", "lcif-grants", "gma"], "src": ["gst"]}, {"id": "gma", "cat": "For members", "level": "member", "title": "Global Membership Approach", "questions": ["global membership approach", "how to grow lions membership", "revitalize a club", "start a new lions club", "get new members for my club", "rebuild a struggling club", "what does gma stand for"], "answer": "The Global Membership Approach is a step-by-step process that helps districts grow. It focuses on starting new clubs and bringing new members into existing clubs, then keeping members engaged. An eLearning course on it is available in the Lions Learning Center.", "facts": ["Related options: Campus clubs, Specialty clubs, Club branches, Young Lions", "Resources include a customizable \"We are Lions\" poster for marketing a club"], "tags": ["membership growth", "gma", "recruit", "new club", "revitalize", "rebuild", "retention"], "related": ["club-types", "mission-1-5"], "src": ["gma"]}, {"id": "mission-1-5", "cat": "For members", "level": "member", "title": "MISSION 1.5", "questions": ["mission 1.5", "1.5 million members goal", "mission 1.5 awards", "lions membership goal"], "answer": "MISSION 1.5 is Lions' goal of reaching 1.5 million members worldwide by 2027. The MISSION 1.5 Awards recognise growth in membership, and the Member Resource Center lists ways to recruit members.", "facts": ["Current membership is about 1.4 million", "Details and the latest award rules are on the Member Resource Center"], "tags": ["mission 1.5", "goal", "1.5 million", "awards", "growth", "2027"], "related": ["gma", "what-is-lions"], "src": ["mrc"]}, {"id": "structure", "cat": "For members", "level": "member", "title": "How Lions is organised", "questions": ["lions structure", "what is a district", "what is a multiple district", "who runs lions clubs international", "district governor", "international president", "how is lions organised", "who leads lions worldwide", "who is in charge of lions", "how do districts work"], "answer": "Lions are organised in layers. Your local club belongs to a district led by a district governor. Districts can be grouped into multiple districts, each with a council chairperson. At the top is Lions Clubs International, led by the International Board of Directors and the International President, with headquarters in Oak Brook, Illinois, USA.", "facts": ["The 2026-27 International President is Mark S. Lyon, elected at the 108th International Convention in Hong Kong (July 2026)", "Each Lions year runs July to June"], "tags": ["structure", "district", "multiple district", "governor", "president", "board", "hierarchy", "who runs"], "related": ["what-is-lions", "contact-lci"], "src": ["mrc", "gst", "lyon-release"]}, {"id": "advocacy", "cat": "For members", "level": "member", "title": "Advocacy for clubs", "questions": ["lions advocacy", "how can clubs advocate", "influence policy lions"], "answer": "Advocacy means a club using its voice to raise awareness, influence laws and policy, and build partnerships around the causes it serves. The Global Service Team toolbox has guidance for it.", "facts": ["Advocacy sits alongside service planning, reporting, awards and grants in the GST toolbox"], "tags": ["advocacy", "policy", "awareness", "partnerships"], "related": ["gst"], "src": ["gst"]}, {"id": "contact-lci", "cat": "Help", "level": "new", "title": "Contact Lions Clubs International", "questions": ["contact lions", "lions headquarters address", "lions phone number", "lions email", "membership email", "where is lions headquarters"], "answer": "Lions Clubs International headquarters is at 300 W. 22nd Street, Oak Brook, Illinois 60523-8842, USA. The main phone is +1 630 571 5466. For membership questions write to membership@lionsclubs.org.", "facts": ["Contact forms are on lionsclubs.org under Contact LCI and Contact LCIF"], "tags": ["contact", "address", "phone", "email", "headquarters", "oak brook", "help"], "related": ["how-to-join"], "src": ["mrc", "leo-lion"]}, {"id": "glossary-lion-portal", "cat": "Glossary", "level": "new", "title": "Lion Portal, MyLCI and Lions Learning Center", "questions": ["what is the lion portal", "what is mylci", "what is lions learning center", "what is the member resource center"], "answer": "These are the online tools for members. The Lion Portal is where you register and manage your Lions account, MyLCI is where clubs maintain membership records, the Lions Learning Center holds online courses, and the Member Resource Center collects news and resources.", "facts": ["Club secretaries typically use MyLCI to update member records"], "tags": ["lion portal", "mylci", "learning center", "member resource center", "online", "tools"], "related": ["new-member-first-steps"], "src": ["new-members", "leo-lion", "mrc"]}, {"id": "glossary-terms", "cat": "Glossary", "level": "new", "title": "Lions jargon in plain words", "questions": ["lions glossary", "what does lci mean", "what is a charter member", "what does charter mean", "lion year", "lions terms", "what is a leo"], "answer": "A Lion is a member. LCI is Lions Clubs International and LCIF is its foundation. A Leo is a youth member aged 12 to 30. Charter means officially founding a club, and charter members are the founding members. A district is a regional group of clubs. The Lions year runs July to June.", "facts": ["A new Lions club needs 20 charter members; a club branch needs five", "GST is the Global Service Team; GMA is the Global Membership Approach"], "tags": ["glossary", "terms", "jargon", "lci", "lcif", "charter", "lion", "leo", "district", "lion year", "meaning"], "related": ["structure", "lcif", "leo-clubs"], "src": ["leo-faqs", "campus", "mrc"]}, {"id": "club-constitution", "cat": "Club rules", "level": "member", "title": "Club Constitution and By-Laws: the overview", "questions": ["club constitution", "what is the club constitution", "club constitution and by laws", "lions club constitution", "what is in the club constitution", "club by-laws", "what are club by-laws", "standard club constitution", "club rules", "lions club rules and regulations", "constitution vs by-laws", "difference between constitution and by-laws"], "answer": "Every Lions club runs under a Constitution and By-Laws, based on a standard form. The Constitution holds the fixed basics: name, purposes, who can be a member, colours and motto, officers, the board, delegates, funds and how to amend it. The By-Laws hold the working detail: membership categories, elections, officer duties, committees, meetings, dues and dispute resolution. Club rules sit below district rules, which sit below the International Constitution.", "facts": ["Constitution: 12 articles (Name, Purposes, Membership, Emblem/Colors/Motto, Supremacy, Club Size, Officers, Board of Directors, Delegates, Club Branch, Club Funds, Amendments)", "By-Laws: 11 articles (Membership, Elections, Officer Duties, Board Positions, Committees, Meetings, Fees and Dues, Club Branch Administration, Miscellaneous, Dispute Resolution, Amendments)", "Constitution changes need two-thirds of members present; By-Law changes need a majority of members present", "Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["club", "constitution", "by-laws", "bylaws", "rules", "standard form", "articles"], "related": ["club-membership-eligibility", "club-membership-categories", "club-officers", "club-elections", "club-board", "club-meetings", "club-committees", "club-fees", "club-amendments", "club-supremacy", "intl-constitution"], "src": ["club-const"]}, {"id": "club-supremacy", "cat": "Club rules", "level": "member", "title": "Which rules come first: club, district or International?", "questions": ["supremacy", "which rules override club constitution", "club constitution conflict with district", "international constitution overrides club", "hierarchy of lions rules", "what if club rules conflict with international"], "answer": "If a club rule conflicts with the district constitution and by-laws, the district's rules control. If it conflicts with the International Constitution, By-Laws or Board policy, the International rules control. Clubs can amend the standard form, but only without conflicting with district or International rules.", "facts": ["Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["supremacy", "conflict", "hierarchy", "district", "international"], "related": ["club-constitution", "intl-constitution"], "src": ["club-const"]}, {"id": "club-membership-eligibility", "cat": "Club rules", "level": "member", "title": "Who can be a member, and how are members admitted?", "questions": ["eligibility for lions membership", "how are members admitted", "membership by invitation", "how to expel a member", "can a member be expelled", "how many members to charter a club", "minimum members for a club charter", "club size"], "answer": "Anyone of legal age, of good moral character and good community reputation can be a member. Admission is by invitation only: a member in good standing sponsors the prospect, the nomination goes to the membership chairperson or secretary, the membership committee investigates, and the board approves by majority. The signed form, entrance fee and dues must reach the secretary before the new Lion is officially recognised. A club should aim for 20 members, the minimum for a charter.", "facts": ["Expulsion for cause needs two-thirds of the entire board", "Expelled members lose the right to use the Lions name, emblem and insignia", "An elected officer must first be removed from office before being expelled", "No one may be a member of two clubs at once (honorary and associate memberships excepted)", "Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["eligibility", "admission", "invitation", "sponsor", "expulsion", "charter", "dual membership"], "related": ["club-membership-categories", "how-to-join"], "src": ["club-const"]}, {"id": "club-membership-categories", "cat": "Club rules", "level": "member", "title": "Membership categories: Active, Honorary, Life and more", "questions": ["membership categories", "what is a life member", "what is an honorary member", "what is an affiliate member", "what is an associate member", "what is a privileged member", "what is member at large", "what is discounted membership", "can honorary members vote", "who counts for delegates", "how much is life membership"], "answer": "The standard by-laws list eight categories. Active members have full rights, including voting and holding office. Member-at-Large is for members who have moved or cannot attend; the board reviews it every six months. Honorary is for a non-member with outstanding service; the club pays their fees. Privileged is for a Lion of 15+ years who must give up active status. Life is for 20+ years of outstanding service (other routes exist) with a one-time payment of US$650. Associate is held by someone whose main club is elsewhere. Affiliate supports the club without full participation. Discounted pays reduced dues under family, student or similar programmes.", "facts": ["Honorary members cannot exceed 5% of total membership; Affiliate members cannot exceed 25%", "Associate and Affiliate members can vote in person but cannot hold office, serve on committees or be delegates", "Discounted category is effective January 1, 2024", "Honorary and Associate members are not counted in the delegate formula", "Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["active", "honorary", "life", "privileged", "affiliate", "associate", "member-at-large", "discounted", "category", "categories"], "related": ["club-good-standing", "club-fees"], "src": ["club-const"]}, {"id": "club-good-standing", "cat": "Club rules", "level": "member", "title": "Good standing, resignation, transfer and reinstatement", "questions": ["good standing", "what is good standing", "how to resign from lions club", "transfer to another lions club", "reinstate a member", "member not paying dues", "dropped for non payment", "how long to pay dues", "rejoin lions club"], "answer": "A member who does not pay a debt within 30 days of the secretary's written notice loses good standing until paid, and only members in good standing can vote or hold office. The secretary reports anyone unpaid 60 days after notice, and the board decides whether to drop them. A resignation takes effect only when the board accepts it, and the board may wait until debts are paid and club property is returned. A member dropped in good standing can be reinstated and keeps earlier service credit; after more than 12 months the normal admission process applies. The same 12-month rule applies to transfers from another club.", "facts": ["Use of the Lions name and emblem ends with membership", "Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["good standing", "resignation", "resign", "transfer", "reinstatement", "dues", "drop"], "related": ["club-membership-categories"], "src": ["club-const"]}, {"id": "club-officers", "cat": "Club rules", "level": "member", "title": "Club officers and their duties", "questions": ["club officers", "who are the club officers", "duties of club president", "what does a lions club president do", "secretary duties", "treasurer duties", "what does the club secretary do", "what does the club treasurer do", "first vice president duties", "membership chairperson duties", "service chairperson duties", "marketing chairperson duties", "immediate past president role", "how to remove a club officer"], "answer": "Club officers are the president, immediate past president, vice president(s), secretary, treasurer, and the service, marketing and membership chairpersons. The president is chief executive: presides at board meetings, chairs the Global Action Team, appoints committees and ensures elections are properly held. The secretary keeps records and reports to Lions Clubs International and the district. The treasurer receives and deposits all money, pays bills only with board authority and chairs the finance committee. The first vice president plans the next president's term and oversees leadership and orientation. Two-thirds of the entire membership can remove an officer for good cause.", "facts": ["Secretary and treasurer post a bond in an amount the board sets", "Immediate past president mentors the president and VPs and is LCIF coordinator unless another Lion is appointed", "Membership chair leads recruitment and retention; service chair sets service goals and reports activities; marketing chair builds the marketing plan and manages social media", "Officers are unpaid except the secretary, whose pay the board may set", "Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["officers", "president", "secretary", "treasurer", "vice president", "chairperson", "duties", "bond", "removal"], "related": ["club-board", "club-elections", "club-board-positions"], "src": ["club-const"]}, {"id": "club-board-positions", "cat": "Club rules", "level": "member", "title": "Other board positions: LCIF coordinator, safety officer, Lion Tamer, Tail Twister", "questions": ["lion tamer", "tail twister", "safety officer", "club lcif coordinator", "program coordinator", "what does a tail twister do", "what does the lion tamer do", "additional board positions", "club director duties"], "answer": "Besides officers, the board can include a program coordinator (books speakers and entertainment), a club LCIF coordinator (promotes LCIF), a safety officer (optional; checks activities for hazards and arranges insurance), a Lion Tamer (optional; looks after club property and acts as sergeant-at-arms), a Tail Twister (optional; brings fun through light fines) and directors who serve two-year terms.", "facts": ["Tail twister fines stay within a cap set by the board; no one is fined more than twice at one meeting", "Fines go to the treasurer with a receipt", "Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["lion tamer", "tail twister", "safety officer", "program coordinator", "director", "lcif coordinator"], "related": ["club-officers", "club-board"], "src": ["club-const"]}, {"id": "club-board", "cat": "Club rules", "level": "member", "title": "Board of Directors: members, quorum and powers", "questions": ["board of directors", "club board", "what does the board of directors do", "board quorum", "club audit", "club bank account", "who authorises club spending", "board powers", "two separate funds", "who is on the board"], "answer": "The board is made up of the club officers plus the other elected directors and chairpersons (and any Lion Tamer, Tail Twister, LCIF coordinator, program coordinator, safety officer and branch president). A majority of directors present in person forms a quorum, and acts need a majority of those present. The board is the executive body: it carries out club policy, authorises all spending, and can modify or rescind an officer's action. It cannot run up debt beyond current income or spend outside member-approved policy.", "facts": ["Arranges an annual audit; members in good standing may inspect it on reasonable request", "Appoints the bank on the finance committee's recommendation and the surety for bonding", "Keeps at least two separate funds: administrative and public/activity", "Net income from public fundraising may not be used for administration", "Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["board", "directors", "quorum", "audit", "spending", "powers"], "related": ["club-funds", "club-officers"], "src": ["club-const"]}, {"id": "club-elections", "cat": "Club rules", "level": "member", "title": "Club elections: nominations, voting and vacancies", "questions": ["club elections", "how are officers elected", "how are lions officers elected", "nominations for officers", "nominating committee", "when are club elections held", "election of directors", "officer vacancy", "what if the president resigns", "secret ballot", "votes needed to win club election", "officers take office"], "answer": "Officers and non-director board members are elected every year and take office on July 1. Half the directors are elected each year for two-year terms. The president appoints a nominating committee. Nominations are held in March (14 days' notice; nominations also allowed from the floor) and the election in April (14 days' notice listing the nominees; no floor nominations). Voting is by secret written ballot of eligible members present. A candidate needs a majority of valid votes cast; the lowest candidate drops out each round until someone has a majority. The secretary reports results to the International Office within 15 days.", "facts": ["Only active members in good standing are eligible", "Dates may be changed by the board", "If the president's seat is vacant, the vice presidents move up in rank order; other vacancies are filled by board appointment for the unexpired term", "If an officer-elect cannot serve, the president may call a special nomination and election with 14 days' notice; plurality is enough", "Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["election", "elections", "nomination", "ballot", "vacancy", "vote", "nominating", "july 1", "officer-elect"], "related": ["club-officers"], "src": ["club-const"]}, {"id": "club-meetings", "cat": "Club rules", "level": "member", "title": "Club meetings: types, notice, quorum and voting", "questions": ["club meetings", "how often do lions clubs meet", "board meeting frequency", "special meeting notice", "annual meeting", "quorum for club meeting", "what is a quorum", "what is quorum", "can a lions club meet online", "teleconference meeting", "voting by mail", "vote by email", "charter anniversary meeting"], "answer": "The board sets its own meeting times; monthly meetings are recommended, and the president or any three board members can call a special board meeting. Clubs are encouraged to have at least one meeting, event or service activity a month, and a service project can replace a meeting. A special club meeting needs at least 10 days' written notice stating the purpose, time and place. The annual meeting is held at the close of the Lions year, when retiring officers report and new officers are installed. Quorum is a majority of members in good standing present in person, and acts need a majority of those present.", "facts": ["Teleconference or web meetings may be held at the president's initiative or at the request of three board members", "Business by mail or electronic vote is effective only if two-thirds of the entire club approve in writing", "Charter anniversary meeting is optional", "Robert's Rules of Order apply unless the documents say otherwise", "Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["meeting", "meetings", "quorum", "notice", "annual meeting", "special meeting", "teleconference", "robert's rules"], "related": ["club-board", "club-amendments", "how-conduct-club-meeting"], "src": ["club-const"]}, {"id": "club-committees", "cat": "Club rules", "level": "member", "title": "Standing committees of a club", "questions": ["club committees", "standing committees", "global action team", "finance committee", "membership committee", "service committee", "what is the global action team", "leadership committee", "constitution and by-laws committee", "information technology committee"], "answer": "Standing committees are appointed by the president (elected chairpersons excepted). They are: Global Action Team (chaired by the president, with the first VP, membership chair and service chair, supported by marketing), Constitution and By-Laws, Finance (chaired by the treasurer), Membership, Marketing, Service, Information Technology and Leadership (chaired by the first VP). The president is an ex-officio member of all committees, and committees report monthly to the board.", "facts": ["Special committees may be appointed by the president with board approval", "Finance prepares the budget and arranges the annual audit; Service can apply for LCIF grants with board approval", "Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["committees", "committee", "global action team", "finance", "membership", "service", "marketing", "leadership"], "related": ["club-officers"], "src": ["club-const"]}, {"id": "club-fees", "cat": "Club rules", "level": "member", "title": "Entrance fees, dues and fiscal year", "questions": ["club dues", "entrance fee", "annual dues", "when are dues paid", "fiscal year of lions club", "lions year july", "how are dues set"], "answer": "New, reinstated and transfer members pay an entrance fee, collected before they are enrolled and reported to Lions Clubs International. Annual dues vary by category, cover International and district dues, and are payable in advance on dates the board sets. Members approve the amounts at the annual meeting. The club's fiscal year runs from July 1 to June 30. The template leaves the amounts blank, so each club sets its own.", "facts": ["Board may waive the club portion of the fee for transfers or reinstatements within 12 months of leaving another club", "Treasurer sends International and district dues on their schedules", "Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["dues", "fees", "entrance fee", "fiscal year", "july 1", "june 30"], "related": ["club-funds", "club-membership-categories"], "src": ["club-const"]}, {"id": "club-funds", "cat": "Club rules", "level": "member", "title": "Club funds: public funds and administrative funds", "questions": ["club funds", "public funds", "administrative funds", "fundraising money", "what is activity fund", "how can club spend fundraiser money", "can club use fundraising money for admin"], "answer": "Clubs keep two kinds of money. Public (activity) funds come from fundraising from the public; all of it, including interest, must go back to public use, and only the direct costs of the fundraiser can be deducted. Administrative funds come from member dues, fines and personal contributions and pay the club's running costs.", "facts": ["Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["funds", "public", "administrative", "fundraising", "money"], "related": ["club-board", "club-fees"], "src": ["club-const"]}, {"id": "club-amendments", "cat": "Club rules", "level": "member", "title": "Amending the club constitution and by-laws", "questions": ["amend constitution", "how to amend club constitution", "change club by-laws", "amendment notice", "constitution amendment vote", "how to change club rules", "votes needed to amend"], "answer": "Constitution: the board must first consider the amendment, then it can pass at a regular or special meeting with a quorum by two-thirds of members present in person and voting. By-Laws: a majority of members present and voting is enough, with no prior board review needed. In both cases written notice must reach every member at least 14 calendar days before the vote.", "facts": ["Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["amendment", "amend", "change", "vote", "notice"], "related": ["club-constitution", "club-meetings"], "src": ["club-const"]}, {"id": "club-branch-rules", "cat": "Club rules", "level": "member", "title": "Club Branch: rules in the constitution", "questions": ["club branch rules", "branch president", "branch officers", "branch funds", "how to dissolve a branch", "branch dues", "branch liaison"], "answer": "A club may form a branch where a full chartered club is not practical. Branch members belong to the parent club, elect a branch president, secretary and treasurer, and have a liaison named by the parent as a fourth officer. The branch president sits on the parent board. Public funds a branch raises go into a designated fund spent in the branch community. A majority of the entire parent membership can disband a branch, and leftover funds return to the parent.", "facts": ["Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["branch", "liaison", "designated funds"], "related": ["club-branch"], "src": ["club-const"]}, {"id": "club-conduct", "cat": "Club rules", "level": "member", "title": "Politics, religion, pay and conduct rules", "questions": ["can lions endorse political candidates", "politics in lions club", "religion in lions meetings", "are officers paid", "can members solicit funds at meeting", "personal benefit membership", "lions neutrality"], "answer": "A club may not endorse political candidates, and members may not debate partisan politics or sectarian religion at meetings. Members may not use membership for personal or political gain. Officers are unpaid, except the secretary, whose pay the board may set. Non-members may not solicit funds from the club at meetings; spending proposals go to a committee or the board.", "facts": ["Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["politics", "religion", "conduct", "compensation", "solicitation", "neutral"], "related": ["club-constitution"], "src": ["club-const"]}, {"id": "club-delegates", "cat": "Club rules", "level": "member", "title": "Delegates to district and International conventions", "questions": ["delegates", "how many delegates", "convention delegates", "international convention delegate", "district convention delegate", "how are delegates chosen"], "answer": "For the International Convention a club gets one delegate and one alternate per 25 members, counting a remainder of 13 or more as a full block, and at least one of each. For district or multiple district conventions it is one per 10 members enrolled at least a year and a day, counting a remainder of 5 or more. The board or its committee names delegates, subject to membership approval, and they must be members in good standing eligible to vote.", "facts": ["Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["delegates", "alternate", "convention"], "related": ["club-membership-categories"], "src": ["club-const"]}, {"id": "club-disputes", "cat": "Club rules", "level": "member", "title": "Resolving disputes in a club", "questions": ["dispute resolution", "club dispute", "member complaint", "how to resolve conflict in lions club", "grievance in club", "dispute between members"], "answer": "Disputes involving members, former members, officers, membership, interpretation of the rules, expulsion or other internal matters that cannot be settled otherwise follow the Dispute Resolution Procedure set by the International Board of Directors. The club president is responsible for handling disputes under that procedure.", "facts": ["Based on the standard club template (FY 2023-24). Your club's own copy may differ: check it, and the current version at lionsclubs.org."], "tags": ["dispute", "conflict", "complaint", "grievance"], "related": ["club-constitution", "club-officers"], "src": ["club-const"]}, {"id": "intl-constitution", "cat": "International rules", "level": "member", "title": "International Constitution and By-Laws: the overview", "questions": ["international constitution", "international by-laws", "international constitution and by-laws", "lions international constitution", "constitution of lions clubs international", "what is in the international constitution", "how is lions international governed"], "answer": "The International Constitution and By-Laws are the highest rules in Lions. Every district and club rule must fit under them. The Constitution (nine articles) covers the name, purposes, membership of clubs, colours and motto, officers and the International Board, conventions and delegates, districts, clubs and amendments. The By-Laws (fourteen articles) cover Board elections, officer duties, committees, Board meetings, the convention, accounts, district organisation and elections, district officers, club membership, fees and dues, rules of order and amendments.", "facts": ["The association is legally 'The International Association of Lions Clubs'", "Membership of the association consists of chartered Lions clubs", "Constitution is amended only at an international convention, by two-thirds of certified delegates voting", "From the International Constitution and By-Laws as revised July 2023. Later amendments may apply: check the current version at lionsclubs.org."], "tags": ["international", "constitution", "by-laws", "bylaws", "association", "governance"], "related": ["intl-purposes", "intl-board", "intl-officer-path", "intl-convention", "intl-districts", "intl-club-obligations", "intl-dues", "intl-amendments"], "src": ["intl-const"]}, {"id": "intl-purposes", "cat": "International rules", "level": "member", "title": "The eight Purposes of Lions Clubs International", "questions": ["purposes of lions clubs", "eight purposes of lions", "international purposes"], "answer": "The International Constitution lists eight Purposes: (a) organise, charter and supervise Lions clubs; (b) coordinate club activities and standardise administration; (c) foster international understanding; (d) promote good government and citizenship; (e) take interest in the civic, cultural, social and moral welfare of the community; (f) unite clubs in friendship and mutual understanding; (g) provide an open forum for public-interest matters, without partisan politics or sectarian religion debate; (h) encourage service without personal financial reward and promote high ethical standards in commerce, industry, professions, public works and private endeavours.", "facts": ["From the International Constitution and By-Laws as revised July 2023. Later amendments may apply: check the current version at lionsclubs.org."], "tags": ["purposes", "objects", "eight", "ethics"], "related": ["intl-constitution", "code-of-ethics"], "src": ["intl-const"]}, {"id": "intl-board", "cat": "International rules", "level": "member", "title": "The International Board of Directors: who sits on it and what it does", "questions": ["international board of directors", "international board", "international directors", "how many international directors", "board powers international", "international president term", "can an international officer be removed", "international budget rules"], "answer": "The International Board is the executive body of the association. It holds corporate powers, supervises officers and committees, controls business, property and funds, and approves the annual budget. It is made up of the executive officers (president, immediate past president and first, second and third vice presidents), the international directors, district governors and administrative officers. Executive officers serve one year; directors serve two years and cannot succeed themselves. Officers are unpaid, with reasonable expenses reimbursed.", "facts": ["Board has 18 directors in even years and 17 in odd years, spread across world regions", "No spending from reserves, unbalanced budget or future-year income without a two-thirds roll-call vote of the entire Board", "An elected officer can be removed for cause by two-thirds of the entire Board", "If the president's office is vacant, the ranking vice president acts until the Board fills it", "Each officer except administrative officers must be an Active Member in good standing", "From the International Constitution and By-Laws as revised July 2023. Later amendments may apply: check the current version at lionsclubs.org."], "tags": ["board", "directors", "executive", "president", "budget", "removal", "terms"], "related": ["intl-officer-path", "intl-board-meetings", "intl-committees"], "src": ["intl-const"]}, {"id": "intl-officer-path", "cat": "International rules", "level": "member", "title": "How International officers are elected: the path to President", "questions": ["how is the international president elected", "how to become international director", "how to become international president", "third vice president candidacy", "director candidate requirements", "endorsement for international director", "international nominating committee", "path to international president"], "answer": "The president, first, second and third vice presidents and all directors are elected by secret ballot at the annual International Convention, by plurality. The path is fixed: a third vice president candidate must have completed a director term and have district endorsement; only a past third VP may run for second VP, a past second VP for first VP, and a past first and second VP for president. A director candidate must be an Active Member in good standing who has served a full term (or major portion) as governor of a full district, and must have district endorsement.", "facts": ["Endorsement documents must arrive 60 days before the convention for directors and 90 days before for third VP", "An endorsement is valid for three succeeding conventions; a director not elected waits three years", "Third VP endorsement allows at most two succeeding endorsements, then a three-year wait", "The president appoints a nine-delegate nominating committee at or within 180 days before the convention", "No two directors may serve at once from the same district", "From the International Constitution and By-Laws as revised July 2023. Later amendments may apply: check the current version at lionsclubs.org."], "tags": ["election", "elected", "president", "vice president", "director", "endorsement", "nominating", "candidate"], "related": ["intl-board", "intl-convention"], "src": ["intl-const"]}, {"id": "intl-convention", "cat": "International rules", "level": "member", "title": "International Convention and delegates", "questions": ["international convention", "who votes at the international convention", "how many delegates per club", "delegate quota international", "proxy voting", "convention quorum", "official call of convention", "delegate entitlement"], "answer": "The annual International Convention is where officers and directors are elected and the Constitution and By-Laws are amended. Each club in good standing sends one delegate and one alternate per 25 members, counting a remainder of 13 or more as a full block, and always at least one of each. Membership is counted from international office records on the first day of the month before the convention month. Each certified delegate present in person has one vote per office and per question. Proxy voting is strictly prohibited at club, district and association level.", "facts": ["Quorum is the certified delegates present in person at any session", "Official call is issued 5 to 60 days before the convention", "Past international presidents and directors have full delegate privileges and are not counted in club quotas", "Convention committees: Credentials, Resolutions, Elections (five or more members each) and Rules of Procedure", "From the International Constitution and By-Laws as revised July 2023. Later amendments may apply: check the current version at lionsclubs.org."], "tags": ["convention", "delegates", "delegate", "proxy", "quorum", "vote", "credentials"], "related": ["intl-officer-path", "intl-amendments", "club-delegates"], "src": ["intl-const"]}, {"id": "intl-districts", "cat": "International rules", "level": "member", "title": "Districts, multiple districts, councils and cabinets", "questions": ["lions districts", "how many clubs for a district", "minimum members for a district", "council of governors", "district cabinet", "who is on the district cabinet", "how are districts formed", "redistricting"], "answer": "Lions territory is divided into single districts, sub-districts and multiple districts. A district needs at least 35 clubs in good standing and 1,250 members in good standing, unless two-thirds of the Board approves otherwise. In a multiple district all the governors form the Council of Governors, with a chairperson who serves one one-year term. Each district's cabinet includes the governor (chair), immediate past governor, first and second vice governors, region chair (if used), zone chair, secretary and treasurer. Redistricting needs a majority vote of the relevant conventions.", "facts": ["Council supervises multiple district affairs, officers, meetings, funds and expenditure", "Council chairperson can be removed for cause by two-thirds of the entire council", "A member may be region or zone chair only over the area where their club is located", "District conventions end at least 30 days (single/sub-district) or 15 days (multiple district) before the International Convention", "From the International Constitution and By-Laws as revised July 2023. Later amendments may apply: check the current version at lionsclubs.org."], "tags": ["district", "multiple district", "council", "cabinet", "governor", "region", "zone", "redistricting"], "related": ["intl-district-governor", "structure"], "src": ["intl-const"]}, {"id": "intl-district-governor", "cat": "International rules", "level": "member", "title": "District Governor: election, qualifications and duties", "questions": ["how is a district governor elected", "district governor qualifications", "district governor duties", "first vice district governor", "second vice district governor", "how to become a district governor", "vice governor requirements"], "answer": "A district governor is elected by secret written ballot at the district convention, needing a majority of valid votes cast by delegates present and voting. The candidate must be an Active Member in good standing, have the endorsement of their club or a majority of district clubs, and be serving as first vice governor. The governor represents the association in the district under Board supervision, leads the Global Action Team and district action plan (new clubs, net membership growth, healthy clubs, leadership training, humanitarian service and support for LCIF), and presides at conventions and cabinet meetings.", "facts": ["Governors and vice governors serve one-year terms and cannot succeed themselves", "Second vice governor candidates need a full term as club president, two more years on a club board, and service as zone chair, region chair or cabinet secretary/treasurer", "If a district fails to elect a qualified governor, the Board may appoint one", "First vice governor is the chief administrative assistant; second vice governor liaises with region and zone chairs", "Zone chair chairs the governor's advisory committee for the zone", "From the International Constitution and By-Laws as revised July 2023. Later amendments may apply: check the current version at lionsclubs.org."], "tags": ["district governor", "governor", "vice governor", "election", "duties", "qualifications"], "related": ["intl-districts"], "src": ["intl-const"]}, {"id": "intl-club-obligations", "cat": "International rules", "level": "member", "title": "Club obligations, charter, status quo and cancellation", "questions": ["how is a club chartered", "what does a club need to stay in good standing", "club status quo", "charter cancelled", "club charter cancellation", "club resignation", "are lions clubs autonomous", "club good standing international", "club name rules"], "answer": "The Board has full authority to organise and charter clubs. A club is chartered when the charter is officially issued, and accepting it binds the club to the Constitution, By-Laws and Board policy. Clubs are autonomous within those rules. To stay in good standing a club must collect minimum annual dues, submit required reports, follow the rules, and try to resolve disputes under the Club Dispute Resolution Procedure. If it fails, the Board, in consultation with governors, may place it in status quo (rights suspended) or cancel its charter.", "facts": ["Club resignation takes effect when the Board accepts it; the Board may wait until debts are paid and the charter, name and emblem are returned", "Club membership is limited to people of legal age, good moral character and reputation, by invitation only", "No one may belong to more than one club, except as Honorary or Associate", "From the International Constitution and By-Laws as revised July 2023. Later amendments may apply: check the current version at lionsclubs.org."], "tags": ["charter", "good standing", "status quo", "cancellation", "autonomous", "obligations"], "related": ["club-membership-eligibility", "club-good-standing"], "src": ["intl-const"]}, {"id": "intl-dues", "cat": "International rules", "level": "member", "title": "International dues, entrance fee and life membership", "questions": ["international dues", "how much are lions international dues", "lions dues amount", "family membership dues", "student membership dues", "life membership cost", "carrying charge", "lions dues increase"], "answer": "In the July 2023 text, international dues are US$23.00 per member per half-year (based on June and December reports), rising to US$24.00 from July 1, 2024 and US$25.00 from July 1, 2025. In family programmes the first member pays full dues and up to four more household members pay half. Eligible students pay half. A Life Member pays a one-time US$650 in place of future international dues. Clubs also pay an annual fee for each Leo club they sponsor. Check the current amounts at lionsclubs.org, because dues can change.", "facts": ["Honorary members' dues are paid by the club", "Past international presidents become Life Members automatically", "Board may charge interest on past-due club balances up to the legal maximum", "From the International Constitution and By-Laws as revised July 2023. Later amendments may apply: check the current version at lionsclubs.org."], "tags": ["dues", "fees", "family", "student", "life member", "international dues", "carrying charge"], "related": ["club-fees", "club-membership-categories"], "src": ["intl-const"]}, {"id": "intl-amendments", "cat": "International rules", "level": "member", "title": "Amending the International Constitution and By-Laws", "questions": ["amend international constitution", "change international by laws", "how is the constitution amended at international level", "amendment international convention", "51 percent district resolutions", "amendment notice international"], "answer": "Both documents change only at an International Convention, on a report from the Committee on Constitution and By-Laws. The Constitution needs two-thirds of certified delegates voting; the By-Laws need a majority. Before the vote, an amendment must either have Board approval, or be backed by district convention resolutions representing at least 51% of all club members as of July 1. Notice must be published in THE LION or another official publication at least 30 days before the vote. By-Law amendments take effect when the convention adjourns unless a later date is stated.", "facts": ["From the International Constitution and By-Laws as revised July 2023. Later amendments may apply: check the current version at lionsclubs.org."], "tags": ["amendment", "amend", "convention", "51%", "notice"], "related": ["intl-convention", "club-amendments"], "src": ["intl-const"]}, {"id": "intl-board-meetings", "cat": "International rules", "level": "member", "title": "International Board meetings and the Executive Committee", "questions": ["international board meetings", "executive committee international", "board quorum international", "business by mail international", "special board meeting", "how often does the international board meet"], "answer": "The Board holds a regular meeting right after the annual convention, others in October or November and in March or April, and a final one at the convention site before it opens. The president can call special meetings, and must call one within 10 days if five directors ask in writing. A quorum is a majority of the Board. Business by mail needs written approval from three-fourths of the entire Board. The Executive Committee (president, immediate past president, vice presidents and one appointed director) acts only when the Board is not assembled; four members make a quorum.", "facts": ["From the International Constitution and By-Laws as revised July 2023. Later amendments may apply: check the current version at lionsclubs.org."], "tags": ["board meeting", "executive committee", "quorum", "mail"], "related": ["intl-board"], "src": ["intl-const"]}, {"id": "intl-committees", "cat": "International rules", "level": "member", "title": "International Board standing committees", "questions": ["international committees", "standing committees international", "audit committee", "convention committee", "leadership development committee", "long range planning committee"], "answer": "Standing committees are appointed by the president with Board approval, each with at least three members. They are Audit; Constitution and By-Laws; Convention; District and Club Service; Finance and Headquarters Operation; Leadership Development; Long Range Planning (at most eight members); Membership Development; Marketing; Service Activities; Technology; and others as needed. Past international officers may serve, but no more than six per fiscal year.", "facts": ["Terms are one year", "The association's accounts are audited annually by certified public accountants; the fiscal year runs July 1 to June 30", "From the International Constitution and By-Laws as revised July 2023. Later amendments may apply: check the current version at lionsclubs.org."], "tags": ["committees", "audit", "finance", "leadership", "marketing", "technology"], "related": ["intl-board"], "src": ["intl-const"]}, {"id": "how-conduct-club-meeting", "cat": "How to", "level": "member", "title": "How to conduct a club meeting, step by step", "questions": ["how to conduct meetings", "how to conduct a meeting", "how to conduct club meeting", "how to run a club meeting", "how to run a meeting", "how to hold a meeting", "how to chair a lions meeting", "meeting agenda", "order of business", "steps to conduct a meeting", "how to lead a meeting", "how do i run a lions meeting", "what is the order of a club meeting"], "answer": "The president calls the meeting and prepares the agenda with the secretary beforehand, then presides. A common order of business is: (1) call to order, on time; (2) roll call and welcome guests; (3) read the previous minutes and ask for corrections or approval; (4) treasurer's report; (5) committee reports; (6) unfinished business; (7) new business; (8) club program or speaker; (9) adjourn. Lions clubs follow Robert's Rules of Order unless their by-laws say otherwise, so motions are proposed, seconded, discussed and voted on in turn. The secretary records the minutes and keeps attendance.", "facts": ["Before: give members notice (special club meetings need at least 10 days' written notice stating purpose, time and place); check quorum, which is a majority of members in good standing present in person", "Order of business above is the common parliamentary pattern, not a Lions-mandated script: clubs adapt it", "A regular meeting can be replaced by a service project or event; at least one meeting, event or activity a month is recommended", "Meetings can be held by teleconference or web conference on the president's initiative or at the request of any three board members", "After: secretary writes up minutes, treasurer's and committee actions are followed up, and the next agenda is drafted"], "tags": ["conduct", "meeting", "agenda", "order of business", "president", "presiding", "chair", "robert's rules", "minutes", "how to"], "related": ["club-meetings", "how-conduct-board-meeting", "club-officers"], "src": ["presidents-deck", "order-business", "order-business2", "club-const"]}, {"id": "how-conduct-board-meeting", "cat": "How to", "level": "member", "title": "How to conduct a club board meeting", "questions": ["how to conduct board meeting", "how to run a board meeting", "board meeting agenda", "how to chair a board meeting", "how to call a board meeting", "executive meeting", "club executive meeting"], "answer": "The club president presides over board meetings and calls them. The board's regular meeting dates are set by the board, and monthly meetings are recommended. A special board meeting can be called by the president or requested by three or more board members. A majority of directors present in person is a quorum, and acts need a majority of those present. A good agenda covers the secretary's minutes, the treasurer's monthly financial report, committee reports, old business and new business, with the board approving all spending.", "facts": ["Treasurer reports payments to the board and gives monthly and semi-annual financial reports", "Committees should report monthly to the board through their chairs, verbally or in writing", "Board shapes new business and policy, and members approve it at a regular or special club meeting", "Agenda items beyond the template are general good practice, not Lions rules"], "tags": ["board meeting", "executive", "agenda", "president", "quorum"], "related": ["club-board", "how-conduct-club-meeting"], "src": ["club-guide-2025", "club-const", "presidents-deck"]}, {"id": "how-conduct-zone-meeting", "cat": "How to", "level": "member", "title": "How to conduct a zone meeting (District Governor's Advisory Committee meeting)", "questions": ["how to conduct zone advisory meeting", "zone meeting", "how to conduct a zone meeting", "district governors advisory committee meeting", "dgac meeting", "zone advisory committee meeting", "how to run a zone meeting", "zone chairperson meeting", "how often are zone meetings held", "what is a zone meeting"], "answer": "A zone meeting, officially the District Governor's Advisory Committee (DGAC) meeting, is chaired by the zone chairperson. Club leaders in the zone come together to share ideas, challenges, best practices and successes. Most zone meetings are held quarterly, often tied to district cabinet dates so time-sensitive news can be shared. To prepare, use the Meeting Preparation Checklist, give club officers the Challenges and Opportunities Worksheet beforehand, and invite the Global Action Team district coordinators (service, membership, leadership) and the LCIF district coordinator. At the meeting, record minutes in the sample format. Afterwards, hand out the Participant's Evaluation, complete the DGAC Report straight away and send it to the district governor, region chairperson and relevant Global Action Team district coordinators.", "facts": ["Attendees: club officers in the zone; district coordinators invited as resources", "Invite the LCIF district coordinator to present on LCIF: how it empowers service in the zone, fundraising goals and grants", "Lions publishes a DGAC Meeting Guide, a zone meeting PowerPoint, minutes format, evaluation form and report in the Member Resource Center under Zone and Region Chairpersons", "The e-Book gives no fixed step-by-step agenda: use the official DGAC Meeting Guide for the suggested agenda"], "tags": ["zone", "zone meeting", "dgac", "advisory committee", "zone chairperson", "district governor", "conduct"], "related": ["zone-chairperson", "intl-districts"], "src": ["zone-ebook", "zone-resources"]}, {"id": "zone-chairperson", "cat": "How to", "level": "member", "title": "What a zone chairperson does", "questions": ["zone chairperson", "what does a zone chairperson do", "zone chairperson duties", "zone chair responsibilities", "region chairperson", "club visits by zone chair"], "answer": "The zone chairperson is the link between the district and the clubs, and the district cabinet member closest to the clubs. Duties include leading the zone meetings (usually quarterly), attending district cabinet meetings, visiting clubs, tracking club health (such as the monthly Club Health Assessment report), helping struggling clubs, and encouraging members to attend the district, multiple district and International conventions. In the first thirty days of the term, the zone chairperson contacts newly elected club officers and shares zone meeting dates.", "facts": ["Reports club concerns to clubstatus@lionsclubs.org", "May install new club officers as the district's representative if asked", "Helps make sure every club has an appointed LCIF club coordinator", "Zone chairperson chairs the governor's advisory committee for the zone and supports club health"], "tags": ["zone chairperson", "zone chair", "region chair", "club visit", "club health"], "related": ["how-conduct-zone-meeting", "intl-district-governor"], "src": ["zone-ebook", "zone-resources"]}, {"id": "titles-overview", "cat": "Officers and titles", "level": "member", "title": "Lions officer titles from club to International, in plain words", "questions": ["what are the lions officer titles", "lions positions and titles explained", "lions hierarchy", "lions ranks", "lions structure from club to international for beginners", "what do all the lions titles mean", "who is who in lions titles and levels"], "answer": "Lions is organised like a ladder, and each rung has its own titles. Club: the president, vice presidents, secretary, treasurer and committee chairpersons run your local club. Zone: a zone chairperson looks after a small group of clubs (a region chairperson looks after several zones, where a district uses regions). District: a district governor, helped by the first and second vice district governors, leads all the clubs in an area, with a cabinet. Multiple district: where several districts are grouped, their governors form a council led by a council chairperson. International: the International President, vice presidents and directors lead the whole association, and the LCIF Chairperson leads the foundation. You only need to know the level you serve at; each rung supports the one below it.", "facts": ["Every Lions year runs July to June, and officers usually serve one year at a time", "A member only becomes a zone, region, district or international officer after serving at club level first", "Ask for any level: club, zone and region, district, multiple district, International, or LCIF area leaders"], "tags": ["titles", "officers", "hierarchy", "ranks", "structure"], "related": ["titles-club", "titles-zone-region", "titles-district", "titles-multiple-district", "titles-international", "lcif-leaders", "structure"], "src": ["mrc", "about-node"]}, {"id": "titles-club", "cat": "Officers and titles", "level": "member", "title": "Positions in a Lions club", "questions": ["what positions are there in a lions club", "who are the officers of a lions club", "what are the club board positions", "what is the immediate past president"], "answer": "In the standard club constitution, the officers are the president, immediate past president, vice president(s), secretary, treasurer, service chairperson, marketing communications chairperson and membership chairperson. The board of directors is made up of those officers plus the Lion tamer, tail twister, club LCIF coordinator, program coordinator, an optional safety officer and, where a club has a branch, the branch president. The president chairs the club's Global Action Team, which is the service chairperson, membership chairperson and the vice president acting as leadership chairperson. Officers are elected for a year.", "facts": ["The Lion tamer looks after club property and order at meetings; the tail twister keeps meetings lively (traditionally with small fines for charity)", "The club LCIF coordinator promotes the foundation and its grants in the club", "Clubs may add other committee chairpersons through their own by-laws", "Based on the standard club constitution and the New Zealand edition of the International officer guide: check your own club's by-laws"], "tags": ["club officers", "positions", "lion tamer", "tail twister", "lcif coordinator", "immediate past president"], "related": ["club-officers", "club-board-positions", "club-board", "how-conduct-club-meeting"], "src": ["club-const", "club-officer-nz"]}, {"id": "titles-zone-region", "cat": "Officers and titles", "level": "member", "title": "Zone chairperson and region chairperson", "questions": ["region chair versus zone chair", "what is the difference between zone and region", "how many clubs in a zone", "who leads a zone"], "answer": "A zone is a small group of neighbouring clubs, and its zone chairperson is the district cabinet member closest to those clubs: visiting them, running zone meetings and helping struggling clubs. Where a district is large it can also group zones into regions, each with a region chairperson who guides the zone chairpersons. Both sit on the district cabinet when the district uses them. A member can only be zone or region chairperson over the area where their own club is located.", "facts": ["The zone chairperson chairs the governor's advisory committee for the zone", "The second vice district governor liaises with the region and zone chairpersons", "Regions are optional: a district uses them only if it needs them"], "tags": ["zone", "region", "zone chair", "region chair"], "related": ["zone-chairperson", "how-conduct-zone-meeting", "titles-district"], "src": ["zone-ebook", "intl-const"]}, {"id": "titles-district", "cat": "Officers and titles", "level": "member", "title": "Positions in a Lions district", "questions": ["what positions are there in a district", "what does the district cabinet secretary do", "district committee chairpersons", "what is a district gmt coordinator", "what is a gat coordinator"], "answer": "A district is led by the district governor. The district cabinet is the governor (chair), the immediate past governor, the first and second vice district governors, the region chairperson if the district uses regions, the zone chairpersons, and the cabinet secretary and treasurer. The first vice governor is the governor's chief assistant and normally becomes governor next; the second vice governor works with the region and zone chairpersons. The governor also leads the district Global Action Team, whose coordinators cover membership (GMT), service (GST), leadership (GLT) and new clubs (GET). Districts also appoint chairpersons for causes and programs such as Leo, vision, diabetes, hunger, childhood cancer, environment, disaster relief, youth camps and exchange, and an LCIF district coordinator.", "facts": ["Governors and vice governors serve one-year terms and cannot succeed themselves", "A district needs at least 35 clubs and 1,250 members unless the Board approves otherwise", "Which committee chairpersons a district has is decided by the governor and the district's own constitution"], "tags": ["district", "cabinet", "vice district governor", "fvdg", "svdg", "gmt", "gst", "glt", "get", "coordinator"], "related": ["intl-district-governor", "intl-districts", "global-action-team", "titles-multiple-district"], "src": ["intl-const", "lcif-toolkit"]}, {"id": "titles-multiple-district", "cat": "Officers and titles", "level": "member", "title": "Council chairperson and council of governors", "questions": ["what is a council chairperson", "what does a multiple district council chairperson do", "what are multiple district coordinators"], "answer": "Where a country or area has several districts, they form a multiple district. All of its district governors make up the Council of Governors, which supervises the multiple district's affairs, officers, meetings and funds. The council elects a chairperson who serves one one-year term and is the link between the governors. The council chairperson also serves as the multiple district chair of the Global Action Team. Multiple districts appoint their own coordinators and chairpersons (for example for membership, service, leadership, new clubs, Leo and LCIF), mirroring the roles in each district.", "facts": ["The council chairperson can be removed for cause by two-thirds of the entire council", "Which officers a multiple district has is set by its own constitution and by-laws", "A single district that is not part of a multiple district is simply called a single district"], "tags": ["council chairperson", "council of governors"], "related": ["intl-districts", "titles-district", "titles-international"], "src": ["intl-const", "lcif-toolkit"]}, {"id": "titles-international", "cat": "Officers and titles", "level": "member", "title": "International officers and directors", "questions": ["who are the international officers", "what is a vice president of lions international", "what is the immediate past international president", "what is a board appointee", "who is the international president now"], "answer": "The executive officers of Lions Clubs International are the International President, the immediate past president and the first, second and third vice presidents. They sit on the International Board of Directors with the elected international directors, the district governors and the administrative officers. Executive officers serve one year; directors serve two years. The Board also has appointees. The 2026-27 International President is Mark S. Lyon. A separate officer, the LCIF Chairperson, leads the Lions Clubs International Foundation.", "facts": ["Officers are elected by secret ballot at the annual International Convention", "The 2025-26 International President was A.P. Singh; Mark S. Lyon was elected at the 108th International Convention in Hong Kong in July 2026", "From the International Constitution and By-Laws as revised July 2023, plus the Lions International news release; check lionsclubs.org for the current list"], "tags": ["international president", "vice president", "director", "international officers", "board appointee"], "related": ["intl-board", "intl-officer-path", "intl-convention", "structure"], "src": ["intl-const", "leaders-page", "lyon-release"]}, {"id": "lcif-leaders", "cat": "Officers and titles", "level": "member", "title": "LCIF area leaders and coordinators", "questions": ["what are lcif area leaders", "what is an lcif coordinator", "what is a district lcif coordinator", "what does the lcif multiple district coordinator do", "who leads lcif"], "answer": "The Lions Clubs International Foundation has its own ladder of volunteers. LCIF area leaders are appointed by the LCIF Chairperson, usually for a three-year term, to represent the foundation across a large area. Below them each multiple district has an LCIF coordinator who acts as an ambassador for LCIF, then district coordinators, and finally the club LCIF coordinator in each club, who promotes giving and grants to members.", "facts": ["LCIF area leaders are appointed by the LCIF Chairperson, usually for three years", "The LCIF Chairperson is a separate role from the International President", "See the LCIF Leadership Toolkit for each role's responsibilities"], "tags": ["lcif", "area leader", "coordinator", "foundation"], "related": ["titles-international", "titles-district", "titles-club"], "src": ["lcif-toolkit"]}, {"id": "logo-brand", "cat": "Marketing", "level": "member", "title": "Using the Lions logo and brand", "questions": ["how do i use the lions logo", "can i use the lions logo", "where can i get the lions logo", "lions logo for my club", "lions brand guidelines", "lions emblem download", "logo permission for a website"], "answer": "Lions International keeps the logo, emblem and brand rules on its Brand Guidelines, Logos and Brand page, so every club's materials look consistent. Brand-approved versions of the Lions emblem, icons and logos for clubs are on the Logos and Emblems page, and the Lions International Brand Guidelines document explains how to use them. Social media kits and Canva templates you can customise for your club are also provided. Use the approved files rather than copying a logo from a website.", "facts": ["Brand guidelines: the Lions International Brand Guidelines document is in the library", "Ready-made social media graphics and Canva templates are on the Social Media Kits page", "If you are unsure whether a use is allowed, ask Lions International before you publish"], "tags": ["logo", "emblem", "brand", "guidelines"], "related": ["titles-club"], "src": ["brand-page"]}, {"id": "lions-acronym", "cat": "About Lions", "level": "new", "title": "What the word LIONS stands for", "questions": ["what does lions stand for", "what does the word lions stand for", "lions acronym", "liberty intelligence our nations safety", "why are they called lions"], "answer": "The name Lions is also read as an acronym: Liberty, Intelligence, Our Nation's Safety. Founder Melvin Jones chose the name Lions because the lion stands for strength, courage, fidelity and vital action. The official motto is simply \"We Serve\".", "facts": ["Liberty, Intelligence, Our Nation's Safety is often called the Lions slogan", "The name was chosen by secret ballot at the founding meeting in Chicago on June 7, 1917", "This comes from a Lions club guide quoting the 1931 issue of The Lion magazine: confirm at lionsclubs.org"], "tags": ["acronym", "liberty", "intelligence", "stand for", "stands for", "lions stand for"], "related": ["motto", "what-is-lions"], "src": ["lions-name"]}]};